import java.util.*;
import java.io.*;

public class Main {
    static int[] tree;
    static int[] dp;
    static int[] factList;
    static int mod;
    static int n;
    static int phiValue;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        phiValue = computePhi(mod);
        int maxLen = n + 5;
        factList = new int[maxLen + 1];
        factList[0] = 1;
        for (int i = 1; i <= maxLen; i++) {
            factList[i] = (int)((long)factList[i - 1] * i % mod);
        }

        if (n <= 3) {
            System.out.println(0);
            return;
        }

        dp = new int[2000];
        dp[0] = 1;
        dp[1] = 2;
        dp[2] = 2;
        dp[3] = 1;

        tree = createSegmentTree(2005);
        for (int i = 0; i < 4; i++) {
            updateNode(i, dp[i]);
        }

        int m = 3;
        long totalAnswer = 0;

        for (int i = 0; i < n - 3; i++) {
            int[] prevDp = Arrays.copyOf(dp, dp.length);
            long partialSumValue = 0;
            for (int j = 0; j <= i + 3 - 1; j++) {
                for (int k = 1; k <= m + 1; k++) {
                    long sumRange = getRangeSum(j + k + 1, 2004);
                    partialSumValue = (partialSumValue + sumRange * prevDp[k - 1]) % mod;
                    int newVal = (int)((long)prevDp[k - 1] + dp[j + k]) % mod;
                    dp[j + k] = newVal;
                    updateNode(j + k, newVal);
                }
            }
            m += i + 3;
            long factorialRange = factorialModRange(i + 4, n);
            totalAnswer = (totalAnswer + factorialRange * partialSumValue) % mod;
        }

        System.out.println(totalAnswer);
    }

    static int[] createSegmentTree(int size) {
        int i = 2;
        while (true) {
            if (i >= size * 2) {
                return new int[i];
            }
            i *= 2;
        }
    }

    static void updateNode(int i, int value) {
        int idx = i + tree.length / 2;
        tree[idx] = value;
        idx /= 2;
        while (idx > 0) {
            tree[idx] = tree[2 * idx] + tree[2 * idx + 1];
            idx /= 2;
        }
    }

    static long getRangeSum(int s, int t) {
        s += tree.length / 2;
        t += tree.length / 2;
        long total = 0;
        while (s <= t) {
            if (s % 2 == 0) {
                s /= 2;
            } else {
                total += tree[s];
                s = (s + 1) / 2;
            }
            if (t % 2 == 1) {
                total += tree[t];
                t = (t - 1) / 2;
            } else {
                t /= 2;
            }
        }
        return total;
    }

    static List<Integer> primeFactorization(int n) {
        List<Integer> factors = new ArrayList<>();
        for (int i = 2; i * i <= n; i++) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
            if (n == 1) {
                break;
            }
        }
        if (n != 1) {
            factors.add(n);
        }
        return factors;
    }

    static int computePhi(int n) {
        Set<Integer> pFactors = new HashSet<>(primeFactorization(n));
        int result = n;
        for (int p : pFactors) {
            result = result * (p - 1) / p;
        }
        return result;
    }

    static long factorialModRange(int a, int b) {
        long res = 1;
        for (int i = a; i <= b; i++) {
            res = (res * i) % mod;
        }
        return res;
    }
}
